body:
{
  "pains": [
    {
      "id": "pain:verification-tax",
      "statement": "Checking what the AI gave me takes longer than if I had just done the work myself.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "The draft or summary comes back fast, but every proposition has to be traced back to the source document or the case before it can go anywhere near a client.",
        "operational": "The time saved on the first pass is handed straight back on the second. Net hours saved are close to zero on anything that matters, so the tool never earns a place in the real workflow.",
        "personal": "They feel stupid for having tried the shortcut, and they stop reaching for the tool on the work that actually counts, which is the only work worth speeding up."
      },
      "workflow": "Research or first-draft stage: prompt in Harvey, CoCounsel or Copilot, output pasted into Word, then Ctrl-F against the underlying PDFs and a second pass through Westlaw or Lexis to confirm each proposition before it reaches a partner.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A junior hands up AI-assisted work on a matter the senior considers vital, and the senior asks for the outputs to be double-checked",
          "cites": ["src:1"]
        },
        {
          "event": "A client's outside counsel guidelines require a human attorney to review anything an LLM produced",
          "cites": ["src:5"]
        }
      ],
      "who_feels": ["end_user", "champion", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "Since it was vital to the case, I asked him to double-check the outputs. But that ended up taking more time than he saved from using AI.",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "every time you use AI, you need to do quality control. You should ask it to show its work and use quotes, so you can make sure its summaries match the content of the patent.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "AI is great for the first and last pass at things.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "Two passes instead of one on exactly the matters where speed would have been worth something, and a growing private rule that the tool is only for low-stakes text.",
          "fears": "That trusting an unverified output once is the day their name ends up on something wrong.",
          "dream_outcome": "Output that arrives already pinned to the paragraph it came from, so verification is a glance rather than a rerun of the work."
        },
        "champion": {
          "says": [
            {
              "situation": "to_their_boss",
              "verbatim": "Educating users about the types of tasks that are best suited to generative AI and how to write effective prompts goes a long way towards mitigating risk.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "Their adoption numbers stall at the exact point where the work gets valuable, and their business case rests on time savings the practice groups quietly do not believe in.",
          "fears": "Being the person who sold a productivity story the partners can disprove from their own timesheets.",
          "dream_outcome": "A tool whose answers carry their own evidence, so the check is built into the output instead of bolted on after."
        }
      },
      "segments": ["seg:biglaw", "seg:midsize-firms", "seg:inhouse"],
      "feature_ref": "feat:agent",
      "cites": ["src:1", "src:5"]
    },
    {
      "id": "pain:fabrication-exposure",
      "statement": "I never thought the thing could just invent a case, and now that is the risk I carry with my name on the filing.",
      "element": "b2b:individual:reputational_assurance",
      "shape": {
        "surface": "Confident, well-formatted citations and quotations that do not exist, sitting inside a document that is about to be signed and filed.",
        "operational": "Sanctions motions, show-cause hearings, withdrawn filings, and a firm-wide clampdown that pushes every practice group back to manual research.",
        "personal": "Public humiliation in a published opinion that follows the lawyer's name forever, and the specific horror of having to explain in open court why they did not check."
      },
      "workflow": "Legal research and brief drafting: a lawyer asks a general model for authority, drops the citations into a memorandum or opposition, and files it through the court's ECF system without independently pulling each case.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "Opposing counsel or the judge cannot locate the cited authorities and orders the filer to produce them",
          "cites": ["src:4"]
        },
        {
          "event": "A client guideline lands that requires disclosure of AI use in time entries or mandates human attorney review",
          "cites": ["src:5"]
        }
      ],
      "who_feels": ["end_user", "blocker", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "greatly regrets having utilized generative artificial intelligence to supplement the legal research performed herein",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "I just never thought it could be made up.",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "Their professional record, in a document anyone can find, for a shortcut that saved an afternoon.",
          "fears": "That the failure mode is invisible until a judge finds it, which means no amount of care at the drafting stage feels like enough.",
          "dream_outcome": "A system where every assertion is traceable to a real document in the firm's own corpus, so fabrication is not a category of error that exists."
        },
        "blocker": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "Any work product created by a Large Language Model (LLM) or other generative AI tool must be reviewed by a human attorney.",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Time spent writing and policing policy instead of doing legal work, and personal exposure if a filing goes wrong on their watch.",
          "fears": "Being the risk owner who approved the tool that produced the sanctionable filing.",
          "dream_outcome": "A tool they can approve once, with grounding and audit trail strong enough that the policy writes itself."
        }
      },
      "segments": ["seg:biglaw", "seg:midsize-firms", "seg:inhouse"],
      "feature_ref": "feat:agent",
      "cites": ["src:4", "src:5", "src:2"]
    },
    {
      "id": "pain:document-pile",
      "statement": "There are hundreds of documents and the only method anyone has given me is to open them one at a time.",
      "element": "b2b:ease_of_doing_business:reduced_effort",
      "shape": {
        "surface": "A data room or production set that has to be read end to end, with the same handful of questions asked of every document and the answers typed into a spreadsheet.",
        "operational": "Weeks of leverage burned on extraction rather than judgment, staffing decisions driven by document count, and write-offs when the client refuses to pay for the volume.",
        "personal": "Twelve-hour days on work that carries no craft, alternating with dead time waiting for the next batch, which is the fastest route to someone quitting."
      },
      "workflow": "Diligence and disclosure: the data room or review platform on one screen, Word or Excel on the other, opening each agreement in turn to answer the same questions about term, change of control, notice period and governing law.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A deal signs and the diligence set lands with a fixed closing date already set",
          "cites": ["src:1"]
        },
        {
          "event": "A review project scales from tens to hundreds of reviewers because the volume cannot be absorbed any other way",
          "cites": ["src:8"]
        }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Sit in front of a computer all day, reading different documents and emails, and then mark into which categories these fall.",
              "cites": ["src:8"]
            },
            {
              "situation": "venting",
              "verbatim": "When there was work it was mind-numbing.",
              "cites": ["src:8"]
            }
          ],
          "costs_them": "Whole weeks of their life on extraction, with no legal skill built and no story to tell about the work.",
          "fears": "That this is what the job is, and that the interesting work never arrives.",
          "dream_outcome": "Every document answering the same set of questions at once, in one table they can sort, challenge and click through to the source."
        },
        "champion": {
          "says": [
            {
              "situation": "when_comparing",
              "verbatim": "It makes those labour-intensive routine tasks such as research and due diligence much quicker, giving our team more time for the interesting work.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "Margin on fixed-fee diligence, and the credibility hit when a client compares the bill to what they think the work should now cost.",
          "fears": "Losing a panel slot to a firm that can quote a diligence exercise in days.",
          "dream_outcome": "Diligence quoted and delivered on a timeline that reads as a differentiator rather than an apology."
        }
      },
      "segments": ["seg:biglaw", "seg:midsize-firms", "seg:inhouse"],
      "feature_ref": "feat:tabular",
      "cites": ["src:8", "src:1", "src:2"]
    },
    {
      "id": "pain:knowhow-buried",
      "statement": "Someone here has done this exact deal before and I have no way of finding what they wrote.",
      "element": "b2b:ease_of_doing_business:information",
      "shape": {
        "surface": "Search across the firm's own documents depends on guessing the words that happen to appear in them, which is precisely what the lawyer does not know.",
        "operational": "Precedent is rebuilt from scratch matter after matter, and the firm's accumulated judgement stays locked in individual inboxes and the memory of whoever ran the last one.",
        "personal": "The quiet embarrassment of emailing round asking whether anyone has a precedent, and the sense that seniority is mostly knowing who to ask."
      },
      "workflow": "Start of a matter: Boolean search in the document management system, then messages to colleagues and practice group distribution lists hunting for a comparable precedent or closing checklist.",
      "type": "latent",
      "confidence": "low",
      "revealed_by": "feat:lists",
      "triggers": [
        {
          "event": "A lawyer tries a semantic search tool over the firm's corpus and cannot predict which keywords will surface the right prior work",
          "cites": ["src:1"]
        }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {},
      "segments": ["seg:biglaw", "seg:midsize-firms"],
      "feature_ref": null,
      "feature_note": "None of the six features in brain/company retrieves the firm's own prior work. Lists and Tabular operate on documents already in hand. What would kill this is grounded retrieval across the firm's DMS and precedent bank, which is not named in the current product record and should be confirmed before it is claimed.",
      "cites": ["src:1"]
    },
    {
      "id": "pain:regulation-blindside",
      "statement": "We find out a rule changed when someone else tells us we are already non-compliant.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "Regulatory change arrives through newsletters, law firm alerts and whoever happened to read the right thing, across every jurisdiction the business touches.",
        "operational": "Remediation projects that would have been cheap if caught early, and outside counsel spend on questions the team should have seen coming.",
        "personal": "The board asks why legal did not flag it, and there is no good answer that is not an admission that nobody was watching."
      },
      "workflow": "Ongoing horizon scanning: regulator websites, subscription alerts and law firm client updates skimmed between matters, with no single place where what changed and what it touches are joined up.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "A new regime lands in an area the team was not tracking and the business is already operating inside it",
          "cites": ["src:2"]
        },
        {
          "event": "Annual planning forces the team to name its biggest challenge for the coming year and compliance demand tops the list",
          "cites": ["src:2"]
        }
      ],
      "who_feels": ["economic_buyer", "end_user", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_looking",
              "verbatim": "AI enables my commercial and legal team to have more time in what is really of value – the analysis of issues and risks, deciding on solutions and mitigation, and commercially-minded support",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "Budget consumed by reactive compliance work and outside counsel questions that early warning would have made unnecessary.",
          "fears": "A regulatory breach that surfaces publicly before legal knew the rule had moved.",
          "dream_outcome": "A standing watch on the regimes that touch the business, surfacing what changed and which contracts or policies it hits, before anyone outside has to point it out."
        }
      },
      "segments": ["seg:inhouse", "seg:biglaw"],
      "feature_ref": "feat:monitors",
      "cites": ["src:2"]
    },
    {
      "id": "pain:confidentiality-wall",
      "statement": "I cannot put client material into a tool I do not control, and losing confidentiality means losing privilege.",
      "element": "b2b:table_stakes:regulatory_compliance",
      "shape": {
        "surface": "The useful work involves privileged and commercially sensitive documents, and those are precisely the documents policy forbids going near a general model.",
        "operational": "AI use gets confined to public material and email polish, and every procurement round restarts the security review from zero.",
        "personal": "The lawyer carries the professional duty personally, so the safe move is to not use the tool at all and never have to defend the decision."
      },
      "workflow": "Procurement and daily use: information security review, client outside counsel guidelines checked before a matter starts, and the individual decision at the prompt box about whether this document can go in.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A client's outside counsel guidelines bar sensitive information from any tool operating in an open environment",
          "cites": ["src:5"]
        },
        {
          "event": "A privilege question is raised about material that passed through a third-party model",
          "cites": ["src:2"]
        }
      ],
      "who_feels": ["blocker", "technical_evaluator", "end_user"],
      "by_role": {
        "blocker": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "Any loss in confidentiality is also a loss in privilege.",
              "cites": ["src:2"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "Never enter Sensitive Information or FDIC work product into a GenAI tool that operates in an 'open environment.'",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Every new tool becomes a security project, and they are the name on the approval if privilege is later argued away.",
          "fears": "An adversary arguing waiver because client material passed through a vendor's model.",
          "dream_outcome": "Certifications, data residency and a contractual no-training commitment strong enough that approval is a document review rather than an argument."
        },
        "technical_evaluator": {
          "says": [
            {
              "situation": "when_comparing",
              "verbatim": "Any work product created by a Large Language Model (LLM) or other generative AI tool must be reviewed by a human attorney.",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Repeated diligence cycles across vendors who cannot evidence their controls.",
          "fears": "Approving a vendor whose posture does not survive a client audit.",
          "dream_outcome": "A vendor whose SOC 2, ISO and no-training position answers the questionnaire before it is sent."
        }
      },
      "segments": ["seg:biglaw", "seg:midsize-firms", "seg:inhouse"],
      "feature_ref": "feat:security",
      "cites": ["src:2", "src:5"]
    },
    {
      "id": "pain:client-sees-nothing",
      "statement": "Our firms say they use AI and we get nothing from it, and next year the same work will cost more.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "The firm announces AI investment, and the client sees identical deliverables arriving on identical timelines with identical or higher invoices.",
        "operational": "Outside counsel spend keeps rising with no observable change in how work is produced or delivered, and the client has no evidence base to push back with.",
        "personal": "The in-house buyer has to defend that spend internally without a single thing they can point to that changed."
      },
      "workflow": "The outside counsel relationship: matter updates by email, deliverables as attachments, and billing reviewed against guidelines after the fact with no window into how the work was produced.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Annual rate review lands and the client compares this year's cost to last year's against a year of AI announcements",
          "cites": ["src:3"]
        },
        {
          "event": "The client writes an AI clause into its outside counsel guidelines requiring disclosure of AI use in time entries",
          "cites": ["src:5"]
        }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "We get nothing. They haven't changed and probably next year the same work will cost even more.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "This can't go on.",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "Legal spend that climbs while the service stays the same, and no leverage in the conversation because nothing is visible.",
          "fears": "Being the GC who kept paying panel rates for work a competitor's panel now does faster and cheaper.",
          "dream_outcome": "Seeing the work as it is produced, and a bill that visibly tracks what the firm actually did."
        },
        "champion": {
          "says": [
            {
              "situation": "to_their_boss",
              "verbatim": "Many firms are investing aggressively in AI without first defining the business and client outcomes those investments are intended to achieve.",
              "cites": ["src:6"]
            }
          ],
          "costs_them": "An AI programme with no client-facing proof point, which makes it a cost line rather than a differentiator at budget time.",
          "fears": "The client conversation happening before the firm has anything to show.",
          "dream_outcome": "A delivery surface the client logs into, where the firm's speed and rigour are visible rather than asserted."
        }
      },
      "segments": ["seg:biglaw", "seg:inhouse"],
      "feature_ref": "feat:portal",
      "cites": ["src:3", "src:5", "src:6"]
    },
    {
      "id": "pain:bought-not-used",
      "statement": "We have the licences and I still cannot tell you what it changed.",
      "element": "b2b:ease_of_doing_business:commitment",
      "shape": {
        "surface": "Seats are deployed, training is delivered, and usage flattens because lawyers cannot connect the tool to a task they actually have.",
        "operational": "Technology spend rising as a share of revenue with no measurement framework capable of showing what it bought, so the next budget request has no evidence behind it.",
        "personal": "The innovation or knowledge lead has staked credibility on a rollout that the practice groups treat as optional."
      },
      "workflow": "Post-rollout: licence dashboards and usage reports reviewed by the innovation or KM team, against practice groups who carry on in Word, Outlook and the DMS exactly as before.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A firm reaches renewal and cannot produce a mature framework for measuring the tool's business impact",
          "cites": ["src:6"]
        },
        {
          "event": "Usage reporting shows lawyers logging in without any repeat workflow forming",
          "cites": ["src:1"]
        }
      ],
      "who_feels": ["champion", "economic_buyer", "end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I don't use AI more because I'm not sure what to use it for.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "I've noticed adoption is stronger in our corporate than litigation groups.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "Another login to ignore, and the nagging sense they are behind without knowing what they are behind on.",
          "fears": "Investing time learning a tool that gets replaced before it pays back.",
          "dream_outcome": "Named workflows for the jobs actually on their desk, so the tool tells them what it is for."
        },
        "champion": {
          "says": [
            {
              "situation": "to_their_boss",
              "verbatim": "No participating firm in Harbor's 2026 legal lab reported having a mature framework for measuring AI's business impact.",
              "cites": ["src:6"]
            }
          ],
          "costs_them": "A budget line they cannot defend and a mandate that erodes each quarter usage stays flat.",
          "fears": "Being the person who spent the firm's AI budget on shelfware.",
          "dream_outcome": "Work products the firm can point to, with usage that grows because the tool does the job rather than assists with it."
        }
      },
      "segments": ["seg:biglaw", "seg:midsize-firms", "seg:inhouse"],
      "feature_ref": "feat:agent",
      "cites": ["src:6", "src:1"]
    },
    {
      "id": "pain:junior-judgment",
      "statement": "If they never built the checklist themselves, they will not know enough to catch it when the machine gets it wrong.",
      "element": "b2b:individual:growth_and_development",
      "shape": {
        "surface": "Juniors reach for AI on exactly the grinding tasks that used to teach them how a deal or a case is actually put together.",
        "operational": "The review layer thins out, because the people whose job is to catch errors were trained by doing the work the machine now does.",
        "personal": "Lawyers notice they retain less of their own matters, and partners quietly lose confidence in work they cannot see the reasoning behind."
      },
      "workflow": "Supervision: a partner reviewing a junior's closing checklist, diligence summary or first draft and probing whether the junior understands why it says what it says.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "A partner reviews AI-assisted junior work and finds the junior cannot answer questions behind it",
          "cites": ["src:1"]
        },
        {
          "event": "A lawyer notices they recall less about a matter they ran with AI than one they read themselves",
          "cites": ["src:1"]
        }
      ],
      "who_feels": ["blocker", "end_user", "champion"],
      "by_role": {
        "blocker": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "If you haven't made the closing checklist or mapped out the triggering conditions for a merger, will you know enough to catch mistakes when they arise?",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "More of their own time on review, because the layer beneath them is less able to catch things.",
          "fears": "A cohort that can operate the tool and cannot do the work, discovered at the worst possible moment.",
          "dream_outcome": "A system that shows its reasoning and its sources, so using it is itself a way of learning how the work is built."
        },
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "it's sometimes harder to remember all the details of a case when I use AI than when I read everything myself.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "Weaker command of their own matters, which shows the moment a partner or client asks an unscripted question.",
          "fears": "Becoming a lawyer who cannot work without the tool.",
          "dream_outcome": "Speed on the mechanical parts without losing the grip on the matter that comes from having been through it."
        }
      },
      "segments": ["seg:biglaw", "seg:midsize-firms"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company addresses how juniors build judgement. The nearest lever is Agent and Tabular exposing their working and sources so supervision remains possible, but that mitigates the pain rather than killing it, and it is a real objection the sales motion will meet from partners.",
      "cites": ["src:1"]
    },
    {
      "id": "pain:inhouse-squeeze",
      "statement": "The work keeps growing, the team does not, and the business treats us as the thing standing in its way.",
      "element": "b2b:functional:scalability",
      "shape": {
        "surface": "Contract volume, compliance demand and business requests all rising against a headcount and budget that are not.",
        "operational": "Triage replaces legal judgement, outside counsel spend rises to absorb the overflow, and the team's value is measured in throughput rather than risk avoided.",
        "personal": "Sustained stress and burnout, concentrated in the senior lawyers who have the least room to hand anything off."
      },
      "workflow": "The in-house queue: intake through email and Slack into a contract system, reviewed between compliance projects and business requests, with escalation to outside counsel when the queue overflows.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Compliance demand is named the team's biggest challenge for the next twelve months while headcount stays flat",
          "cites": ["src:2"]
        },
        {
          "event": "Outside counsel bills rise and the team rates its panel firms as poor value",
          "cites": ["src:7", "src:3"]
        }
      ],
      "who_feels": ["economic_buyer", "end_user", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_looking",
              "verbatim": "AI enables my commercial and legal team to have more time in what is really of value – the analysis of issues and risks, deciding on solutions and mitigation, and commercially-minded support",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "We get nothing. They haven't changed and probably next year the same work will cost even more.",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "Outside counsel spend they cannot justify and a team they cannot grow, so every new demand lands on people already at capacity.",
          "fears": "Losing senior lawyers to burnout and having nothing to replace them with.",
          "dream_outcome": "Routine volume handled end to end in-house, so the team's hours go to the judgement calls only they can make."
        }
      },
      "segments": ["seg:inhouse"],
      "feature_ref": "feat:agent",
      "cites": ["src:2", "src:7", "src:3"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "Practitioners name specific tools unprompted and compare them against each other and against doing the work by hand, so they know the problem and know a category exists. What they do not have is a settled view of which product wins, or evidence that any of them changes the work rather than assisting with it.",
      "cites": ["src:1", "src:6"]
    },
    "seg:biglaw": {
      "level": "product",
